	/**
	 * A replay-only decision never refreshes and is never served stale. Under a Frontier move it re-plans; under a move
	 * in learned state alone it is served only when its planning's read log still replays (phase B), and re-plans when
	 * a recorded read changed or with the read-log switch off (the rule before phase B).
	 */
	@ParameterizedTest
	@CsvSource({ "frontier,IDENTICAL,true", "leo,CHANGED,true", "leo,IDENTICAL,false", "leo,IDENTICAL,true" })
	void replayOnlyEntryNeverRefreshesOrServesStaleUnderChangedLearnedEvidence(String changedEvidence,
			LmdbPlanningReadLog.Verdict replay, boolean validation) {
		String previousSwitch = System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY,
				Boolean.toString(validation));
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, 1, 1024 * 1024L);
		try {
			LmdbPipelinePlanCache.Context context = LmdbPlanCacheRevalidationTest.learned(17L, 2L, 3L, 7L, 0L, true);
			LmdbPipelinePlanCache.Context changed = "frontier".equals(changedEvidence)
					? LmdbPlanCacheRevalidationTest.learned(17L, 20L, 3L, 7L, 0L, true)
					: LmdbPlanCacheRevalidationTest.learned(17L, 2L, 30L, 7L, 0L, true);
			LmdbPlanCacheRevalidationTest.StubValidator validator = new LmdbPlanCacheRevalidationTest.StubValidator(
					replay, LmdbPlanningReadLog.EXACT_FACT);
			AtomicInteger computations = new AtomicInteger();
			AtomicInteger refreshes = new AtomicInteger();
			PackedPlanDecisionSummary summary = unavailableSummary(false,
					PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT);
			QueryRoot source = query("_anon_1", "urn:left");
			LmdbPlanDecisionCache.DetachedRefreshWork refreshWork = refreshWork(source, changed, refreshes, null,
					null, null);
			cache.getOrComputePlan(source, context, context::revision,
					() -> new LmdbPipelinePlanCache.PlanComputation(unpriced(source, computations), summary,
							refreshWork),
					() -> Long.MIN_VALUE, validator);
			QueryRoot identical = query("_anon_2", "urn:left");
			var replayed = cache.getOrComputePlan(identical, context, context::revision,
					() -> new LmdbPipelinePlanCache.PlanComputation(unpriced(identical, computations), summary,
							refreshWork),
					() -> Long.MIN_VALUE, validator);
			assertTrue(replayed.cacheHit());
			assertEquals(1, computations.get());

			QueryRoot drifted = query("_anon_3", "urn:left");
			var next = cache.getOrComputePlan(drifted, changed, changed::revision,
					() -> new LmdbPipelinePlanCache.PlanComputation(unpriced(drifted, computations), summary,
							refreshWork),
					() -> Long.MIN_VALUE, validator);

			boolean revalidated = "leo".equals(changedEvidence) && replay == LmdbPlanningReadLog.Verdict.IDENTICAL
					&& validation;
			if (revalidated) {
				assertTrue(next.cacheHit(), "a learned-only move with an unchanged log serves the replay");
				assertEquals(LmdbPlanCacheRevalidation.REVALIDATED,
						next.plan().getStringMetricPlanned("optimizer.planCacheRefreshReason"));
				assertEquals(1, computations.get());
			} else {
				assertFalse(next.cacheHit(), "changed evidence must re-plan a replay-only decision");
				assertEquals(2, computations.get());
			}
			assertEquals("frontier".equals(changedEvidence) || !validation ? 0 : 1, validator.calls.get(),
					"only a learned-only move is replayed, and only with the switch on");
			assertEquals(0L, decisionCache(cache).statistics().refreshUses());
			assertEquals(0L, refreshTaskCount(cache), "a replay-only decision never submits detached refresh");
			assertEquals(0, refreshes.get());
		} finally {
			cache.close();
			restore(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, previousSwitch);
		}
	}

