				QueryRoot source = query("_anon_" + request, "urn:left");
				var result = cache.getOrComputePlan(source, context, context::revision, () -> {
					// A planning-time read (for example foreground filter sampling) was cut by its time limit.
					LmdbPlanningWallClockCuts.recordCut();
					return new LmdbPipelinePlanCache.PlanComputation(unpriced(source, computations), summary, null);
				});
