	@Test
	void lifecycleBlockedReplayIsNotRepublishedAndIsReclaimedBeforeLiveFamilies() {
		// Family capacity two: a third family needs a slot.
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(2, 1, 1024 * 1024L);
		try {
			LmdbPipelinePlanCache.Context context = context(17L);
			AtomicInteger computations = new AtomicInteger();
			PackedPlanDecisionSummary unavailable = unavailableSummary(false,
					PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT);
			QueryRoot cold = query("_anon_1", "urn:left");
			statementPattern(cold).setRuntimeFeedbackContract(runtimeFeedbackContract());
			cache.getOrComputePlan(cold, context, context::revision,
					() -> new LmdbPipelinePlanCache.PlanComputation(unpriced(cold, computations), unavailable, null));
			QueryRoot hotSource = query("_anon_2", "urn:left");
			var hot = cache.getOrComputePlan(hotSource, context, context::revision,
					() -> new LmdbPipelinePlanCache.PlanComputation(unpriced(hotSource, computations), unavailable,
							null));
			LmdbPlanDecisionCache.PlanExecutionToken token = ((LmdbRuntimeFeedbackDescriptor) statementPattern(
					hot.plan()).getRuntimeFeedbackContract().descriptor()).planExecutionToken();
			cache.observeExecution(new LmdbPlanDecisionCache.ExecutionObservation(token.familyKey(),
					token.variantId(), token.planVersion(), true, false, 1d, 0L, true, false));
			QueryRoot liveSource = query("_anon_1", "urn:live");
			cache.getOrCompute(liveSource, context, context::revision, () -> planned(liveSource, computations));
			long publications = decisionCache(cache).statistics().publications();

			for (int replan = 0; replan < 3; replan++) {
				QueryRoot again = query("_anon_r" + replan, "urn:left");
				assertFalse(cache.getOrComputePlan(again, context, context::revision,
						() -> new LmdbPipelinePlanCache.PlanComputation(unpriced(again, computations), unavailable,
								null))
						.cacheHit());
			}
			assertEquals(publications, decisionCache(cache).statistics().publications(),
					"the retired decision is not re-published under the evidence that retired it");

			QueryRoot oneOff = query("_anon_1", "urn:once");
			cache.getOrCompute(oneOff, context, context::revision, () -> planned(oneOff, computations));
			QueryRoot oneOffAgain = query("_anon_2", "urn:once");
			assertTrue(cache.getOrCompute(oneOffAgain, context, context::revision,
					() -> planned(oneOffAgain, computations)).cacheHit(),
					"a retired replay is reclaimed before any live family, without proof of reuse");
			QueryRoot liveAgain = query("_anon_2", "urn:live");
			assertTrue(cache.getOrCompute(liveAgain, context, context::revision,
					() -> planned(liveAgain, computations)).cacheHit());
		} finally {
			cache.close();
		}
	}

