	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void retiredDecisionIsNotRepublishedAfterItsFamilyIsReclaimedUntilTheEvidenceChanges(boolean ranked) {
		// Family capacity two: a third family needs a slot.
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(2, 1, 1024 * 1024L);
		try {
			LmdbPipelinePlanCache.Context initial = context(17L);
			LmdbPipelinePlanCache.Context revised = context(18L);
			AtomicInteger computations = new AtomicInteger();
			publishAndRetire(cache, initial, ranked, computations);
			QueryRoot liveSource = query("_anon_1", "urn:live");
			cache.getOrCompute(liveSource, initial, initial::revision, () -> planned(liveSource, computations));
			QueryRoot oneOff = query("_anon_1", "urn:once");
			cache.getOrCompute(oneOff, initial, initial::revision, () -> planned(oneOff, computations));
			QueryRoot oneOffAgain = query("_anon_2", "urn:once");
			assertTrue(cache.getOrCompute(oneOffAgain, initial, initial::revision,
					() -> planned(oneOffAgain, computations)).cacheHit(), "fixture: the retired family is reclaimed");
			long publications = decisionCache(cache).statistics().publications();

			for (int replan = 0; replan < 3; replan++) {
				QueryRoot again = query("_anon_r" + replan, "urn:left");
				assertFalse(cache.getOrComputePlan(again, initial, initial::revision,
						() -> decision(ranked, again, computations)).cacheHit(), "replan=" + replan);
			}
			assertEquals(publications, decisionCache(cache).statistics().publications(),
					"a retired decision is not re-published under the evidence that retired it, also after its "
							+ "family was reclaimed");

			// New evidence clears the retirement: the key is cached again like any key that proves its reuse.
			boolean cached = false;
			for (int request = 0; request < 3 && !cached; request++) {
				QueryRoot revisedSource = query("_anon_v" + request, "urn:left");
				cached = cache.getOrComputePlan(revisedSource, revised, revised::revision,
						() -> decision(ranked, revisedSource, computations)).cacheHit();
			}
			assertTrue(cached, "a re-plan under new evidence is published again");
		} finally {
			cache.close();
		}
	}

