	@Test
	void planThatFitsAggregateDecisionBudgetIsNotRejectedByRoutingSegmentShare() {
		LmdbPipelinePlanCache.Context context = context(17L);
		LmdbPipelinePlanCache measuringCache = new LmdbPipelinePlanCache(8, 1, 1024 * 1024L);
		AtomicInteger measuringComputations = new AtomicInteger();
		QueryRoot measuredSource = query("_anon_1", "urn:left");

		measuringCache.getOrCompute(measuredSource, context, context::revision,
				() -> planned(measuredSource, measuringComputations));
		long exactEntryBytes = measuringCache.retainedBytes();
		measuringCache.close();
		assertTrue(exactEntryBytes > 0L);

		// A cold publish transiently reserves its input identity before it charges the steady-state entry, so the
		// aggregate budget must exceed one entry. It still leaves each half of a two-way split below one entry.
		long budget = 2L * exactEntryBytes - 1L;
		assertTrue(budget / 2L < exactEntryBytes, "a partitioned share could not hold the entry");
		for (int segments : new int[] { 1, 2 }) {
			LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, segments, budget);
			try {
				AtomicInteger computations = new AtomicInteger();
				QueryRoot coldSource = query("_anon_2", "urn:left");
				LmdbPipelinePlanCache.Result cold = cache.getOrCompute(coldSource, context, context::revision,
						() -> planned(coldSource, computations));
				QueryRoot hotSource = query("_anon_3", "urn:left");
				LmdbPipelinePlanCache.Result hot = cache.getOrCompute(hotSource, context, context::revision,
						() -> planned(hotSource, computations));

				assertFalse(cold.cacheHit(), "segments=" + segments);
				assertTrue(hot.cacheHit(),
						"routing segments must not partition the store-owned decision budget; segments=" + segments);
				assertEquals(1, computations.get(), "segments=" + segments);
				assertEquals(exactEntryBytes, cache.retainedBytes(), "segments=" + segments);
			} finally {
				cache.close();
			}
		}
	}

